20: // StageGroup holds features for a single stage, preserving order.
21: type StageGroup struct {
22: 	Stage    string
23: 	Features []FeatureSummary
24: }
25: 
26: // groupFeaturesByStage returns features organized by stage in canonical order.
27: // Stages with zero features are included so the UI can show empty columns.
28: func groupFeaturesByStage(features []FeatureSummary) []StageGroup {
29: 	byStage := make(map[string][]FeatureSummary)
30: 	for _, f := range features {
31: 		byStage[f.Stage] = append(byStage[f.Stage], f)
32: 	}
33: 	groups := make([]StageGroup, 0, len(stageOrder))
34: 	for _, s := range stageOrder {
35: 		groups = append(groups, StageGroup{Stage: s, Features: byStage[s]})
36: 	}
37: 	// Include any stages not in the canonical list (defensive)
38: 	for stage, feats := range byStage {
39: 		found := false
40: 		for _, s := range stageOrder {
41: 			if s == stage {
42: 				found = true
43: 				break
44: 			}
45: 		}
46: 		if !found {
47: 			groups = append(groups, StageGroup{Stage: stage, Features: feats})
48: 		}
49: 	}
50: 	return groups
51: }
