63: func checkAPIAuth(r *http.Request, apiKey string) bool {
64: 	if apiKey == "" {
65: 		return true
66: 	}
67: 	// Check ?key= query parameter
68: 	if r.URL.Query().Get("key") == apiKey {
69: 		return true
70: 	}
71: 	// Check Authorization: Bearer <key>
72: 	if auth := r.Header.Get("Authorization"); auth != "" {
73: 		if strings.HasPrefix(auth, "Bearer ") && strings.TrimPrefix(auth, "Bearer ") == apiKey {
74: 			return true
75: 		}
76: 	}
77: 	// Check X-API-Key header
78: 	if r.Header.Get("X-API-Key") == apiKey {
79: 		return true
80: 	}
81: 	return false
82: }
