97: func registerRoutes(mux *http.ServeMux, hub *Hub, cfg *Config) {
98: 	funcMap := template.FuncMap{
99: 		"groupByStage": groupFeaturesByStage,
100: 		"stageLabel": func(s string) string {
101: 			return strings.ReplaceAll(s, "-", " ")
102: 		},
103: 		"toJSON": func(v interface{}) string {
104: 			b, _ := json.Marshal(v)
105: 			return string(b)
106: 		},
107: 		"uniqueBoards": func(features []FeatureSummary) string {
108: 			seen := map[string]bool{}
109: 			var boards []string
110: 			for _, f := range features {
111: 				if f.Board != "" && !seen[f.Board] {
112: 					seen[f.Board] = true
113: 					boards = append(boards, f.Board)
114: 				}
115: 			}
116: 			return strings.Join(boards, ", ")
117: 		},
118: 	}
119: 	tmpl := template.Must(template.New("").Funcs(funcMap).ParseFS(templateFS, "templates/*.html"))
120: 
121: 	// Static files
122: 	mux.Handle("/static/", http.FileServer(http.FS(staticFS)))
123: 
124: 	// Dashboard page
125: 	mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
126: 		// Only handle exact "/" path; let other handlers catch their paths
127: 		path := r.URL.Path
128: 		if path != "/" {
129: 			// Check if it matches /clients/{id}
130: 			if strings.HasPrefix(path, "/clients/") {
131: 				serveClientPage(w, r, hub, tmpl, cfg)
132: 				return
133: 			}
134: 			http.NotFound(w, r)
135: 			return
136: 		}
137: 		key := r.URL.Query().Get("key")
138: 		authenticated := key != "" && (cfg.DashboardKey == "" || key == cfg.DashboardKey)
139: 		clients := hub.ListClients()
140: 		// Aggregate all features across all clients, stamping client ID
141: 		var allFeatures []FeatureSummary
142: 		for _, c := range clients {
143: 			for _, f := range c.Features {
144: 				f.ClientID = c.ClientID
145: 				allFeatures = append(allFeatures, f)
146: 			}
147: 		}
148: 		data := map[string]interface{}{
149: 			"Clients":       clients,
150: 			"Key":           key,
151: 			"Authenticated": authenticated,
152: 			"StageGroups":   groupFeaturesByStage(allFeatures),
153: 		}
154: 		w.Header().Set("Content-Type", "text/html")
155: 		if err := tmpl.ExecuteTemplate(w, "index.html", data); err != nil {
156: 			log.Printf("template error: %v", err)
157: 			http.Error(w, "internal server error", 500)
158: 		}
159: 	})
160: 
161: 	// API: list clients (and sub-paths /api/clients/{id}, /api/clients/{id}/logs)
162: 	apiClientsHandler := func(w http.ResponseWriter, r *http.Request) {
163: 		// Check if this is /api/clients/{id} or /api/clients/{id}/logs
164: 		trimmed := strings.TrimPrefix(r.URL.Path, "/api/clients")
165: 		trimmed = strings.TrimPrefix(trimmed, "/")
166: 		if trimmed != "" {
167: 			parts := strings.SplitN(trimmed, "/", 2)
168: 			clientID := parts[0]
169: 			if len(parts) == 2 {
170: 				sub := parts[1]
171: 				if sub == "logs" {
172: 					serveClientLogs(w, r, hub, cfg, clientID)
173: 					return
174: 				}
175: 				if sub == "auto-mode" {
176: 					serveAutoMode(w, r, hub, cfg, clientID)
177: 					return
178: 				}
179: 				if sub == "ideas" {
180: 					serveCreateIdea(w, r, hub, cfg, clientID)
181: 					return
182: 				}
183: 				// Match features/{fid}/answers or features/{fid}/start-agent
184: 				if strings.HasPrefix(sub, "features/") {
185: 					featureParts := strings.SplitN(strings.TrimPrefix(sub, "features/"), "/", 2)
186: 					featureID := featureParts[0]
187: 					if len(featureParts) == 2 && featureParts[1] == "answers" && featureID != "" {
188: 						serveSubmitAnswers(w, r, hub, cfg, clientID, featureID)
189: 						return
190: 					}
191: 					if len(featureParts) == 2 && featureParts[1] == "start-agent" && featureID != "" {
192: 						serveStartAgent(w, r, hub, cfg, clientID, featureID)
193: 						return
194: 					}
195: 				}
196: 			}
197: 			serveClientJSON(w, r, hub, cfg, clientID)
198: 			return
199: 		}
200: 
201: 		if !checkAPIAuth(r, cfg.APIKey) {
202: 			writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "unauthorized"})
203: 			return
204: 		}
205: 
206: 		clients := hub.ListClients()
207: 		key := r.URL.Query().Get("key")
208: 
209: 		// If HTMX request, return HTML fragment
210: 		if r.Header.Get("HX-Request") != "" {
211: 			w.Header().Set("Content-Type", "text/html")
212: 			data := map[string]interface{}{
213: 				"Clients": clients,
214: 				"Key":     key,
215: 			}
216: 			if err := tmpl.ExecuteTemplate(w, "client_rows", data); err != nil {
217: 				log.Printf("template error: %v", err)
218: 				http.Error(w, "internal server error", 500)
219: 			}
220: 			return
221: 		}
222: 
223: 		writeJSON(w, http.StatusOK, clients)
224: 	}
225: 	mux.HandleFunc("/api/clients", apiClientsHandler)
226: 	mux.HandleFunc("/api/clients/", apiClientsHandler)
227: 
228: 	// HTMX fragment: board view (all features grouped by stage)
229: 	mux.HandleFunc("/api/board", func(w http.ResponseWriter, r *http.Request) {
230: 		if !checkDashboardAuth(r, cfg.DashboardKey) {
231: 			http.Error(w, "unauthorized", http.StatusUnauthorized)
232: 			return
233: 		}
234: 		clients := hub.ListClients()
235: 		var allFeatures []FeatureSummary
236: 		for _, c := range clients {
237: 			for _, f := range c.Features {
238: 				f.ClientID = c.ClientID
239: 				allFeatures = append(allFeatures, f)
240: 			}
241: 		}
242: 		w.Header().Set("Content-Type", "text/html")
243: 		data := map[string]interface{}{
244: 			"StageGroups": groupFeaturesByStage(allFeatures),
245: 			"Key":         r.URL.Query().Get("key"),
246: 		}
247: 		if err := tmpl.ExecuteTemplate(w, "board_fragment", data); err != nil {
248: 			log.Printf("template error: %v", err)
249: 			http.Error(w, "internal server error", 500)
250: 		}
251: 	})
252: 
253: 	// Favicon
254: 	mux.HandleFunc("/favicon.svg", func(w http.ResponseWriter, r *http.Request) {
255: 		data, err := staticFS.ReadFile("static/favicon.svg")
256: 		if err != nil {
257: 			http.NotFound(w, r)
258: 			return
259: 		}
260: 		w.Header().Set("Content-Type", "image/svg+xml")
261: 		w.Header().Set("Cache-Control", "public, max-age=86400")
262: 		w.Write(data)
263: 	})
264: 
265: 	// Service worker (served from root for scope)
266: 	mux.HandleFunc("/sw.js", func(w http.ResponseWriter, r *http.Request) {
267: 		data, err := staticFS.ReadFile("static/sw.js")
268: 		if err != nil {
269: 			http.NotFound(w, r)
270: 			return
271: 		}
272: 		w.Header().Set("Content-Type", "application/javascript")
273: 		w.Header().Set("Service-Worker-Allowed", "/")
274: 		w.Header().Set("Cache-Control", "no-cache")
275: 		w.Write(data)
276: 	})
277: 
278: 	// WebSocket endpoint
279: 	mux.HandleFunc("/ws", func(w http.ResponseWriter, r *http.Request) {
280: 		// Auth via query param or header
281: 		authorized := false
282: 		if cfg.APIKey == "" {
283: 			authorized = true
284: 		} else {
285: 			if r.URL.Query().Get("api_key") == cfg.APIKey {
286: 				authorized = true
287: 			} else if checkAPIAuth(r, cfg.APIKey) {
288: 				authorized = true
289: 			}
290: 		}
291: 		if !authorized {
292: 			writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "unauthorized"})
293: 			return
294: 		}
295: 
296: 		conn, err := upgrader.Upgrade(w, r, nil)
297: 		if err != nil {
298: 			log.Printf("websocket upgrade error: %v", err)
299: 			return
300: 		}
301: 
302: 		client := &Client{
303: 			hub:      hub,
304: 			conn:     conn,
305: 			send:     make(chan []byte, 256),
306: 			clientID: "unknown",
307: 			state: &ClientState{
308: 				ClientID:  "unknown",
309: 				Features:  []FeatureSummary{},
310: 				Logs:      []LogEntry{},
311: 				Connected: true,
312: 			},
313: 		}
314: 
315: 		hub.register <- client
316: 		go client.writePump()
317: 		go client.readPump()
318: 	})
319: }
