321: func serveSubmitAnswers(w http.ResponseWriter, r *http.Request, hub *Hub, cfg *Config, clientID string, featureID string) {
322: 	if r.Method != http.MethodPost {
323: 		writeJSON(w, http.StatusMethodNotAllowed, map[string]string{"error": "method not allowed"})
324: 		return
325: 	}
326: 	if !checkDashboardAuth(r, cfg.DashboardKey) && !checkAPIAuth(r, cfg.APIKey) {
327: 		writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "unauthorized"})
328: 		return
329: 	}
330: 
331: 	// Parse request body
332: 	body, err := io.ReadAll(io.LimitReader(r.Body, 1*1024*1024))
333: 	if err != nil {
334: 		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "failed to read body"})
335: 		return
336: 	}
337: 	var req struct {
338: 		Answers []QuestionAnswer `json:"answers"`
339: 	}
340: 	if err := json.Unmarshal(body, &req); err != nil {
341: 		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "invalid JSON"})
342: 		return
343: 	}
344: 
345: 	// Validate client exists and is connected
346: 	state, ok := hub.GetClient(clientID)
347: 	if !ok {
348: 		writeJSON(w, http.StatusNotFound, map[string]string{"error": "client not found"})
349: 		return
350: 	}
351: 	if !state.Connected {
352: 		writeJSON(w, http.StatusUnprocessableEntity, map[string]string{"error": "client not connected"})
353: 		return
354: 	}
355: 
356: 	// Validate feature exists and is in requested-input stage
357: 	var found bool
358: 	for _, f := range state.Features {
359: 		if f.ID == featureID {
360: 			found = true
361: 			if f.Stage != "requested-input" {
362: 				writeJSON(w, http.StatusUnprocessableEntity, map[string]string{"error": "feature not in requested-input stage"})
363: 				return
364: 			}
365: 			break
366: 		}
367: 	}
368: 	if !found {
369: 		writeJSON(w, http.StatusNotFound, map[string]string{"error": "feature not found"})
370: 		return
371: 	}
372: 
373: 	// Send answer_questions message to client via WebSocket
374: 	msg, _ := json.Marshal(map[string]interface{}{
375: 		"type":       "answer_questions",
376: 		"feature_id": featureID,
377: 		"answers":    req.Answers,
378: 	})
379: 	if err := hub.SendToClient(clientID, msg); err != nil {
380: 		writeJSON(w, http.StatusUnprocessableEntity, map[string]string{"error": err.Error()})
381: 		return
382: 	}
383: 
384: 	writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
385: }
