438: func serveStartAgent(w http.ResponseWriter, r *http.Request, hub *Hub, cfg *Config, clientID string, featureID string) {
439: 	if r.Method != http.MethodPost {
440: 		writeJSON(w, http.StatusMethodNotAllowed, map[string]string{"error": "method not allowed"})
441: 		return
442: 	}
443: 	if !checkDashboardAuth(r, cfg.DashboardKey) && !checkAPIAuth(r, cfg.APIKey) {
444: 		writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "unauthorized"})
445: 		return
446: 	}
447: 
448: 	body, err := io.ReadAll(io.LimitReader(r.Body, 1*1024*1024))
449: 	if err != nil {
450: 		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "failed to read body"})
451: 		return
452: 	}
453: 	var req struct {
454: 		Action string `json:"action"`
455: 	}
456: 	if err := json.Unmarshal(body, &req); err != nil {
457: 		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "invalid JSON"})
458: 		return
459: 	}
460: 	if req.Action != "plan" && req.Action != "implement" {
461: 		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "invalid action, must be 'plan' or 'implement'"})
462: 		return
463: 	}
464: 
465: 	state, ok := hub.GetClient(clientID)
466: 	if !ok {
467: 		writeJSON(w, http.StatusNotFound, map[string]string{"error": "client not found"})
468: 		return
469: 	}
470: 	if !state.Connected {
471: 		writeJSON(w, http.StatusUnprocessableEntity, map[string]string{"error": "client not connected"})
472: 		return
473: 	}
474: 
475: 	// Find feature and validate stage
476: 	var feature *FeatureSummary
477: 	for i := range state.Features {
478: 		if state.Features[i].ID == featureID {
479: 			feature = &state.Features[i]
480: 			break
481: 		}
482: 	}
483: 	if feature == nil {
484: 		writeJSON(w, http.StatusNotFound, map[string]string{"error": "feature not found"})
485: 		return
486: 	}
487: 
488: 	// Check stage is allowed for this action
489: 	allowedStages, hasAction := state.StageActions[req.Action]
490: 	if !hasAction {
491: 		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "stage actions not available"})
492: 		return
493: 	}
494: 	stageAllowed := false
495: 	for _, s := range allowedStages {
496: 		if s == feature.Stage {
497: 			stageAllowed = true
498: 			break
499: 		}
500: 	}
501: 	if !stageAllowed {
502: 		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "feature stage '" + feature.Stage + "' not valid for action '" + req.Action + "'"})
503: 		return
504: 	}
505: 
506: 	// Check agent not busy
507: 	if req.Action == "plan" && state.PlanAgent.Running {
508: 		writeJSON(w, http.StatusConflict, map[string]string{"error": "plan agent is already running"})
509: 		return
510: 	}
511: 	if req.Action == "implement" && state.ImplAgent.Running {
512: 		writeJSON(w, http.StatusConflict, map[string]string{"error": "implement agent is already running"})
513: 		return
514: 	}
515: 
516: 	// Send start_agent message to client via WebSocket
517: 	msg, _ := json.Marshal(map[string]interface{}{
518: 		"type":       "start_agent",
519: 		"feature_id": featureID,
520: 		"action":     req.Action,
521: 	})
522: 	if err := hub.SendToClient(clientID, msg); err != nil {
523: 		writeJSON(w, http.StatusUnprocessableEntity, map[string]string{"error": err.Error()})
524: 		return
525: 	}
526: 
527: 	writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
528: }
